-- ---------------------------------------------------------------------------
-- POSTFLIGHT: hard guards (any violation → COMMIT below never runs → rollback)
-- ---------------------------------------------------------------------------
do $post015$
declare
  v_rest integer; v_places integer; v_unver integer; v_coords integer;
  v_nolink integer; v_nosrc integer; v_temple integer; v_hotel integer; v_other integer;
begin
  select count(*) into v_rest from public.restaurants where source = 'tptm-b15';
  if v_rest <> 40 then
    raise exception 'POSTFLIGHT FAIL: expected 40 batch-015 restaurant rows, found %.', v_rest;
  end if;
  select count(*) into v_places from public.places where source = 'tptm-b15';
  if v_places <> 19 then
    raise exception 'POSTFLIGHT FAIL: expected 19 batch-015 place rows, found %.', v_places;
  end if;

  select count(*) into v_unver from public.restaurants where source = 'tptm-b15' and verification_status <> 'unverified';
  v_unver := v_unver + (select count(*) from public.places where source = 'tptm-b15' and verification_status <> 'unverified');
  if v_unver <> 0 then
    raise exception 'POSTFLIGHT FAIL: % rows are not unverified — an import never self-verifies.', v_unver;
  end if;

  select count(*) into v_coords from public.restaurants where source = 'tptm-b15' and (latitude is not null or longitude is not null);
  v_coords := v_coords + (select count(*) from public.places where source = 'tptm-b15' and latitude is not null);
  if v_coords <> 0 then
    raise exception 'POSTFLIGHT FAIL: expected ZERO coordinate rows (published OSM coords stay in evidence), found %.', v_coords;
  end if;

  select count(*) into v_nolink from public.places where source = 'tptm-b15' and destination_id is null;
  if v_nolink <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing destination linkage.', v_nolink;
  end if;

  select count(*) into v_nosrc from public.places where source = 'tptm-b15' and (source_url is null or source_url = '');
  if v_nosrc <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing source_url.', v_nosrc;
  end if;

  select count(*) filter (where place_type = 'temple') into v_temple from public.places where source = 'tptm-b15';
  select count(*) filter (where place_type = 'hotel') into v_hotel from public.places where source = 'tptm-b15';
  select count(*) filter (where place_type = 'other') into v_other from public.places where source = 'tptm-b15';
  if v_temple <> 3 or v_hotel <> 1 or v_other <> 15 then
    raise exception 'POSTFLIGHT FAIL: place_type distribution drifted (temple=% hotel=% other=%; expected 3/1/15).', v_temple, v_hotel, v_other;
  end if;
  raise notice 'POSTFLIGHT OK: 59 rows verified (40 restaurants + 19 places; temple 3, hotel 1, other 15).';
end
$post015$;

commit;
